helpers=r'''
function advanceCelebration(s,now){let changed=false;if(s.celebration&&now>=s.celebration.endsAt){s.celebration=null;changed=true;}s.celebrationQueue??=[];if(!s.celebration&&s.celebrationQueue.length){const next=s.celebrationQueue.shift();s.celebration={...next,startedAt:now,endsAt:now+next.duration};changed=true;}return changed;}
function revealCorrect(s,now){if(!s.serial)return;const key=s.round+':'+s.serial;s.revealedQuestions??=[];if(s.revealedQuestions.includes(key))return;s.revealedQuestions.push(key);s.revealedQuestions=s.revealedQuestions.slice(-200);const people=[...new Map((s.choices||[]).filter(p=>!p.demo&&p.answer===s.answer).map(p=>[p.id,p])).values()];s.celebrationQueue??=[];for(let i=0;i<people.length;i++){const p=people[i];s.celebrationQueue.push({id:'correct:'+key+':'+p.id,kind:'correct',person:{...p},round:s.round,serial:s.serial,gained:10,points:s.players.find(x=>x.id===p.id)?.points||10,ordinal:i+1,total:people.length,duration:2500});}advanceCelebration(s,now);}
function revealWinners(s,now){const ranked=[...(s.players||[])].filter(p=>(p.answerPoints??p.correct*10)>0).sort((a,b)=>(b.answerPoints??b.correct*10)-(a.answerPoints??a.correct*10));if(!ranked.length)return;const score=ranked[0].answerPoints??ranked[0].correct*10,people=ranked.filter(p=>(p.answerPoints??p.correct*10)===score);s.celebrationQueue??=[];for(let i=0;i<people.length;i++){const p=people[i];s.celebrationQueue.push({id:'winner:'+s.round+':'+p.id,kind:'winner',person:{...p},round:s.round,points:p.points,ordinal:i+1,total:people.length,duration:6500});}advanceCelebration(s,now);s.resultUntil=Math.max(now,s.celebration?.endsAt||now)+s.celebrationQueue.reduce((n,x)=>n+x.duration,0);}
'''
